import{z as n,x as s,o as A,c as o,q as l,j as e,D as a,d as i,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"失败模式与收束","description":"","frontmatter":{"title":"失败模式与收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-map.md","filePath":"llm/rag-map.md","lastUpdated":1791063341000}'),F={name:"llm/rag-map.md"};function p(d,E,m,D,h,_){const B=s("Mermaid");return A(),o("div",null,[E[2]||(E[2]=l('<h1 id="失败模式与收束" tabindex="-1">失败模式与收束 <a class="header-anchor" href="#失败模式与收束" aria-label="Permalink to &quot;失败模式与收束&quot;">​</a></h1><div class="epigraph"><p>生产的故障都长在端到端上，病根埋在某一层里；排查法就是从症状走到层、从层走到旋钮的那张地图。</p><footer>—— 据本课程整理</footer></div><p><a href="/llm/rag-incremental-consistency">上一课</a>把更新与版本一致性立起来，至此检索工程与语义与生产两个单元全部落地。本课做两件事：把失败编成跨层排查法，把课程收进几条线。这是本课程最后一课——本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生产故障的表现永远在端到端：答错、答旧、拒答、泄漏、引用虚构。缺的是从症状到层的协议：先问<a href="/llm/RAG-eval-triangle">评测三角</a>里哪一角变了，再问该角对应哪几课的旋钮。没有协议的团队会在错误的一层反复调参——检索明明给对了，却在调提示；生成明明在抄错，却在换嵌入。收束的问题因此不是复述，是提炼：前十一课里哪些是跨层不变的结构，哪些只是本次部署的常数。</p><p><span class="marginnote">常见误区：初学者容易「哪里不对改哪里」——答案不好就换提示词、换模型，改了十几处还是时好时坏。没有先问「三角哪一角变了」，你连故障出在检索还是生成都不知道；两层参数互相打架，任何单点修改都会被另一层的噪声淹没。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按层的失败清单，每层三件套：症状、验证、旋钮。</p><ul><li>解析与切分：金标跨度覆盖率低、引用粒度碎——修抽取与切分策略（第一课）。</li><li>嵌入：域内查询集体偏、近邻不相关——看域漂移与微调（第二课）。</li><li>索引：p99 抖、难查询切片召回掉——重画曲线、查过滤交互（第三课）。</li><li>融合：某类查询系统性偏一路——查权重漂移、退回 RRF（第四课）。</li><li>重排：前排精度低、拒答率异常——查 \\(m\\) 饱和与阈值（第五课）。</li><li>查询理解：多跳断链、改写跑偏——关切片改写、查路由（第六课）。</li><li>结构化与多模态：聚合口径错、图表数值错——查 schema 卡与数值校验（第七、八课）。</li><li>生成：忠实度掉、引用不可解析——查提示、顺序与归因（第九课）。</li><li>时间维度：答旧、幽灵块——查对账与通道同步（第十一课）。</li><li>安全：被诱导引用毒块——查鉴权、隔离与多源一致（<a href="/llm/retrieval-poisoning-defense">投毒防御</a>）。</li></ul><p>排查纪律：一次只动一层的一个旋钮，动前动后跑三角，分数与版本三元组一起存档。</p><p><span class="marginnote">术语翻译：每层的「三件套」就是病历写法——症状（用户看到了什么）、验证（用什么数据确认病根在这层）、旋钮（这层有哪个参数可调）。排查纪律「一次只动一个旋钮」就是控制变量实验：同时改两个，好了不知道归谁，坏了不知道赖谁。</span></p>',11)),(A(),e(t,null,{default:a(()=>[r(B,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E7%97%87%E7%8A%B6%22%5D%20--%3E%20TRI%5B%22%E4%B8%89%E8%A7%92%E5%AE%9A%E4%BD%8D%EF%BC%9A%E5%93%AA%E4%B8%80%E8%A7%92%E5%8F%98%E4%BA%86%22%5D%0A%20%20TRI%20--%3E%20L1%7B%22%E6%A3%80%E7%B4%A2%E8%A7%92%E6%8E%89%EF%BC%9F%22%7D%0A%20%20L1%20--%3E%7C%E6%98%AF%7C%20RAG1%5B%22%E5%88%87%E5%88%86%20%2F%20%E5%B5%8C%E5%85%A5%20%2F%20%E7%B4%A2%E5%BC%95%20%2F%20%E8%9E%8D%E5%90%88%20%2F%20%E9%87%8D%E6%8E%92%22%5D%0A%20%20TRI%20--%3E%20L2%7B%22%E5%BF%A0%E5%AE%9E%E5%BA%A6%E6%8E%89%EF%BC%9F%22%7D%0A%20%20L2%20--%3E%7C%E6%98%AF%7C%20GEN%5B%22%E6%8F%90%E7%A4%BA%20%2F%20%E9%A1%BA%E5%BA%8F%20%2F%20%E5%BD%92%E5%9B%A0%22%5D%0A%20%20TRI%20--%3E%20L3%7B%22%E7%9B%B8%E5%85%B3%E6%88%96%E6%97%B6%E6%95%88%E6%8E%89%EF%BC%9F%22%7D%0A%20%20L3%20--%3E%7C%E6%98%AF%7C%20QURY%5B%22%E6%9F%A5%E8%AF%A2%E7%90%86%E8%A7%A3%20%2F%20%E5%A2%9E%E9%87%8F%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20RAG1%20--%3E%20FIX%5B%22%E5%8A%A8%E4%B8%80%E5%B1%82%E4%B8%80%E4%B8%AA%E6%97%8B%E9%92%AE%EF%BC%8C%E9%87%8D%E8%B7%91%E4%B8%89%E8%A7%92%22%5D%0A%20%20GEN%20--%3E%20FIX%0A%20%20QURY%20--%3E%20FIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收束回大图。本课程十二课是同一句话的展开：RAG 工程是把「检索什么、给多少、怎么排、何时信、如何更新」全部变成可测量、可门禁、可回滚的对象。检索工程单元（切分、嵌入、索引、融合、重排）给测量对象；语义与生产单元（查询理解、结构化、多模态、评测、预算、更新）给行为对象。与主干的分工：<a href="/llm/rag-chunking">向量检索与切分</a>、<a href="/llm/hybrid-retrieval">混合检索</a>、<a href="/llm/rerank">重排序</a>立第一性与默认，本课程把默认变成你自己分布上的实测决策——协议（金标、三角、版本三元组、门禁、对账）跨语料与模型复用，常数（块长、\\(M\\)、\\(m\\)、权重）每次换代重测。</p>',2)),(A(),e(t,null,{default:a(()=>[r(B,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20COURSE%5B%22RAG%20%E7%B3%BB%E7%BB%9F%E6%B7%B1%E5%85%A5%3A%20%E5%8D%81%E4%BA%8C%E8%AF%BE%22%5D%20--%3E%20UNIT1%5B%22%E6%A3%80%E7%B4%A2%E5%B7%A5%E7%A8%8B%E5%8D%95%E5%85%83%3A%20%E6%B5%8B%E9%87%8F%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20COURSE%20--%3E%20UNIT2%5B%22%E8%AF%AD%E4%B9%89%E4%B8%8E%E7%94%9F%E4%BA%A7%E5%8D%95%E5%85%83%3A%20%E8%A1%8C%E4%B8%BA%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20UNIT1%20--%3E%20A1%5B%22%E5%88%87%E5%88%86%20%2F%20%E5%B5%8C%E5%85%A5%20%2F%20%E7%B4%A2%E5%BC%95%22%5D%0A%20%20UNIT1%20--%3E%20A2%5B%22%E8%9E%8D%E5%90%88%20%2F%20%E9%87%8D%E6%8E%92%22%5D%0A%20%20UNIT2%20--%3E%20B1%5B%22%E6%9F%A5%E8%AF%A2%E7%90%86%E8%A7%A3%20%2F%20%E7%BB%93%E6%9E%84%E5%8C%96%20%2F%20%E5%A4%9A%E6%A8%A1%E6%80%81%22%5D%0A%20%20UNIT2%20--%3E%20B2%5B%22%E8%AF%84%E6%B5%8B%20%2F%20%E9%A2%84%E7%AE%97%20%2F%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20A1%20--%3E%20P%5B%22%E8%B7%A8%E5%B1%82%E5%8D%8F%E8%AE%AE%3A%20%E9%87%91%E6%A0%87%20%2F%20%E4%B8%89%E8%A7%92%E9%97%A8%E7%A6%81%20%2F%20%E7%89%88%E6%9C%AC%E4%B8%89%E5%85%83%E7%BB%84%20%2F%20%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20A2%20--%3E%20P%0A%20%20B1%20--%3E%20P%0A%20%20B2%20--%3E%20P%0A%20%20P%20--%3E%7C%22%E5%8D%8F%E8%AE%AE%E5%A4%8D%E7%94%A8%22%7C%20KEEP%5B%22%E6%8D%A2%E4%BB%A3%E4%BB%8D%E6%88%90%E7%AB%8B%22%5D%0A%20%20P%20--%3E%7C%22%E5%B8%B8%E6%95%B0%E9%87%8D%E6%B5%8B%22%7C%20RETEST%5B%22%E5%9D%97%E9%95%BF%20%2F%20M%20%2F%20m%20%2F%20%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<p><span class="marginnote">直觉类比：协议像体检流程——量血压、验血、对比历史，换了个病人照样适用；常数像处方剂量——同一个流程开出的克数因人而异。换嵌入模型相当于换病人：流程照走，但上一版测出的块长、\\(M\\)、融合权重一个都不能直接抄。</span></p><p><span class="marginnote">一句自检：任何「RAG 优化」若说不清动的是三角哪一角、版本三元组哪一维、门禁哪条线，它就还是一个技巧——技巧在语料或模型换代时静默失效，协议不会。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>清单不能替代三角数据：先看指标在哪层变，再动旋钮；反着来就是玄学调参。深钻层收束一门课，不收束一个领域：语料、嵌入、查询分布都会换代，本课程的曲线与常数会过期，协议不过期。检索之后的推理——多跳之后的规划、反思与预算分配——属于推理链与规划的课，此处交接。维护一张活的失败台账：每个新故障按本课三件套入册，台账比清单多一层时间，是团队真正的记忆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排查协议：症状到三角角度，角度到层，层到旋钮；一次动一个。</li><li>十一课收两线：检索工程给测量对象，语义与生产给行为对象。</li><li>主干立第一性，深钻把你自己的分布变成决策；协议复用，常数重测。</li><li>跨层不变的结构：金标跨度、三角门禁、版本三元组、对账台账。</li><li>检索之后的推理另课交接；失败台账随时间生长。</li><li>出处：本课程各课口径汇总；Lewis 等 RAG、Karpukhin 等 DPR、Es 等 RAGAS 等见各课小节。</li></ul>',6))])}const c=n(F,[["render",p]]);export{T as __pageData,c as default};
